insert into passages (id, text, difficulty_level, b, active) values
('bdaa277c-f414-4112-97cd-6a9acf95ae32', 'The Dunning-Kruger effect, a cognitive bias first described by psychologists David Dunning and Justin Kruger in 1999, describes the tendency of individuals with limited knowledge or skill in a given domain to overestimate their own competence, while those with greater expertise often underestimate their relative ability compared to others. The proposed explanation for this asymmetry is that the very skills required to perform a task well are often the same skills needed to accurately evaluate one''s own performance; a person who lacks competence in a domain therefore also lacks the metacognitive ability to recognize that lack. Experts, by contrast, tend to be acutely aware of the complexity of their field and may mistakenly assume that tasks which come easily to them are equally easy for everyone else, leading them to underrate their own distinctiveness. Although the effect has become a popular shorthand in casual discourse, frequently invoked to explain everything from workplace incompetence to political overconfidence, some statisticians have argued that at least part of the observed pattern can be attributed to a purely statistical phenomenon known as regression to the mean, rather than to any genuine psychological deficiency in self-assessment. This critique does not necessarily invalidate the underlying psychological mechanism Dunning and Kruger proposed, but it does suggest that popular applications of the concept often extend well beyond what the original research can support.', 4, 1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('51a5bc27-8dab-4649-9aab-46e6daddf7d0', 'sentence_completion', 'The mayor''s proposal, though well received publicly, was privately regarded by advisors as fiscally ___.', NULL, '[{"id": "c", "text": "reckless"}, {"id": "a", "text": "sound"}, {"id": "b", "text": "prudent"}, {"id": "d", "text": "conservative"}]'::jsonb, 0, '{"strategy": "though well received publicly, privately regarded = למרות קבלה פומבית, נתפס באופן פרטי אחרת. ניגוד.", "correct_reason": "reckless = פזיז. הצעה שהתקבלה טוב פומבית אך נחשבת בעייתית כלכלית באופן פרטי היא פזיזה.", "options_analysis": ["נכון! reckless = פזיז — מתאים לניגוד בין קבלה פומבית לביקורת פרטית", "sound = איתן — הפוך מדעה פרטית ביקורתית שנרמזת", "prudent = זהיר — הפוך מדעה פרטית ביקורתית", "conservative = שמרני — הפוך מדעה פרטית ביקורתית שמרמזת על סיכון"]}', 1.15, 1.0, 0.25, 4, 'ai', NULL, true),
('eaf2c47e-d227-430d-95e8-8bf3387f5fc6', 'sentence_completion', 'The negotiator''s tendency to ___ every point, however minor, often prolonged discussions unnecessarily.', NULL, '[{"id": "b", "text": "accept"}, {"id": "a", "text": "contest"}, {"id": "d", "text": "overlook"}, {"id": "c", "text": "concede"}]'::jsonb, 1, '{"strategy": "prolonged discussions unnecessarily = האריך דיונים שלא לצורך. איזו התנהגות עם כל נקודה קטנה מאריכה דיונים?", "correct_reason": "contest = לערער/להתווכח על. ערעור על כל נקודה, גם קטנה, מאריך דיונים.", "options_analysis": ["accept = לקבל — הפוך מהתנהגות שמאריכה דיונים", "נכון! contest = להתווכח על — מתאים להתנהגות שמאריכה דיונים שלא לצורך", "overlook = להתעלם — הפוך מהתנהגות שמאריכה דיונים על כל נקודה", "concede = לוותר — הפוך מהתנהגות שמאריכה דיונים"]}', 1.15, 1.0, 0.25, 4, 'ai', NULL, true),
('1ab276a1-c0f5-4f70-8bb8-d296495ebca1', 'sentence_completion', 'The author''s memoir was praised for its refusal to ___ her own shortcomings, presenting an unusually candid self-portrait.', NULL, '[{"id": "c", "text": "reveal"}, {"id": "a", "text": "confront"}, {"id": "b", "text": "gloss over"}, {"id": "d", "text": "expose"}]'::jsonb, 2, '{"strategy": "unusually candid self-portrait = דיוקן עצמי כן באופן חריג. איזו התנהגות עם חסרונות עצמיים מנוגדת לכנות?", "correct_reason": "gloss over = להעביר בשטחיות/להחליק על. סירוב להחליק על חסרונות עצמיים מוביל לדיוקן כן.", "options_analysis": ["reveal = לגלות — הפוך מהתנהגות שנמנעת מכנות", "confront = להתעמת עם — הפוך מהתנהגות שנמנעת מכנות", "נכון! gloss over = להחליק על — מתאים לסירוב שמוביל לדיוקן כן", "expose = לחשוף — הפוך מהתנהגות שנמנעת מכנות"]}', 1.74, 1.0, 0.25, 4, 'ai', NULL, true),
('1d5b6251-e772-4888-8f0a-eab7481c6e7f', 'sentence_completion', 'Despite the CEO''s efforts to project confidence, her ___ tone during the interview suggested underlying doubt.', NULL, '[{"id": "d", "text": "commanding"}, {"id": "b", "text": "resolute"}, {"id": "c", "text": "assured"}, {"id": "a", "text": "hesitant"}]'::jsonb, 3, '{"strategy": "despite efforts to project confidence...suggested underlying doubt = למרות מאמצים להקרין ביטחון...רמז לספק. ניגוד.", "correct_reason": "hesitant = מהוסס. טון מהוסס למרות מאמץ להיראות בטוחה מרמז על ספק.", "options_analysis": ["commanding = שתלטני/מפקד — הפוך מרמז לספק פנימי", "resolute = נחוש — הפוך מרמז לספק פנימי", "assured = בטוח — הפוך מרמז לספק פנימי", "נכון! hesitant = מהוסס — מתאים לניגוד בין מאמץ להקרין ביטחון לספק פנימי"]}', 1.6, 1.0, 0.25, 4, 'ai', NULL, true),
('b18a8b7a-4c74-4c79-8e6a-c4df4b45c379', 'sentence_completion', 'The historian''s account, meticulously researched, nonetheless contained several ___ that later scholars identified.', NULL, '[{"id": "b", "text": "inaccuracies"}, {"id": "c", "text": "confirmations"}, {"id": "a", "text": "achievements"}, {"id": "d", "text": "strengths"}]'::jsonb, 0, '{"strategy": "nonetheless contained...later identified = ובכל זאת הכיל...חוקרים מאוחרים זיהו. ניגוד בין מחקר קפדני לפגמים שנמצאו.", "correct_reason": "inaccuracies = אי-דיוקים. מחקר קפדני עדיין יכול להכיל אי-דיוקים שמאוחר יותר מתגלים.", "options_analysis": ["נכון! inaccuracies = אי-דיוקים — מתאים לפגמים שחוקרים מאוחרים מזהים", "confirmations = אישושים — לא הגיוני שחוקרים ''מזהים'' אישושים כבעיה", "achievements = הישגים — לא הגיוני בהקשר של ''nonetheless''", "strengths = חוזקות — לא הגיוני שחוקרים ''יזהו'' חוזקות כבעיה"]}', 1.65, 1.0, 0.25, 4, 'ai', NULL, true),
('de885e00-35e9-41c8-b371-2b6685318564', 'sentence_completion', 'The board''s ___ approach to risk management left the company exposed when the market suddenly shifted.', NULL, '[{"id": "c", "text": "rigorous"}, {"id": "d", "text": "lax"}, {"id": "b", "text": "cautious"}, {"id": "a", "text": "careful"}]'::jsonb, 1, '{"strategy": "left the company exposed = השאיר את החברה חשופה. איזו גישה לניהול סיכונים משאירה חברה חשופה?", "correct_reason": "lax = רופפת/לא קפדנית. גישה רופפת לניהול סיכונים משאירה חברה חשופה.", "options_analysis": ["rigorous = קפדנית — הפוך מהשארת החברה חשופה", "נכון! lax = רופפת — מתאים להשארת החברה חשופה לסיכון", "cautious = זהירה — הפוך מהשארת החברה חשופה", "careful = זהירה — הפוך מהשארת החברה חשופה"]}', 1.33, 1.0, 0.25, 4, 'ai', NULL, true),
('8017c658-f279-457e-aeb9-922eea613d06', 'sentence_completion', 'The critic''s assessment, while ___ in tone, ultimately acknowledged the film''s technical achievements.', NULL, '[{"id": "d", "text": "complimentary"}, {"id": "c", "text": "positive"}, {"id": "a", "text": "critical"}, {"id": "b", "text": "favorable"}]'::jsonb, 2, '{"strategy": "while...ultimately acknowledged achievements = בעוד...בסופו של דבר הכיר בהישגים. ניגוד בין טון לתוצאה.", "correct_reason": "critical = ביקורתי. טון ביקורתי שבכל זאת מכיר בהישגים יוצר את הניגוד המתאים.", "options_analysis": ["complimentary = מחמיא — לא יוצר ניגוד עם ''ultimately acknowledged''", "positive = חיובי — לא יוצר ניגוד עם ההכרה בהישגים", "נכון! critical = ביקורתי — יוצר ניגוד הגיוני עם ההכרה בהישגים בסוף", "favorable = חיובי — לא יוצר ניגוד עם ההכרה בהישגים"]}', 1.31, 1.0, 0.25, 4, 'ai', NULL, true),
('15099cd7-0a88-442d-882b-cb0dc1015394', 'sentence_completion', 'The investigation revealed that the company''s financial statements had been ___ for several years.', NULL, '[{"id": "d", "text": "accurate"}, {"id": "c", "text": "verified"}, {"id": "a", "text": "audited"}, {"id": "b", "text": "falsified"}]'::jsonb, 3, '{"strategy": "the investigation revealed = החקירה חשפה. מה חשיפת חקירה על דוחות כספיים מרמזת?", "correct_reason": "falsified = מזויפים. חקירה שחושפת בעיה בדוחות כספיים מרמזת על זיוף.", "options_analysis": ["accurate = מדויקים — לא הגיוני שחקירה ''תחשוף'' דיוק כבעיה", "verified = מאומתים — לא הגיוני שחקירה ''תחשוף'' אימות כבעיה", "audited = מבוקרים — לא הגיוני שחקירה ''תחשוף'' ביקורת כבעיה", "נכון! falsified = מזויפים — מתאים לחשיפה בחקירה כבעיה חמורה"]}', 1.23, 1.0, 0.25, 4, 'ai', NULL, true),
('0ef1b398-75ca-4080-9690-9210ed775de9', 'sentence_completion', 'The senator''s ___ remarks about the opposing party drew immediate backlash from both sides of the aisle.', NULL, '[{"id": "d", "text": "inflammatory"}, {"id": "c", "text": "measured"}, {"id": "b", "text": "diplomatic"}, {"id": "a", "text": "balanced"}]'::jsonb, 0, '{"strategy": "drew immediate backlash from both sides = משכה תגובה שלילית מיידית משני הצדדים. איזו הערה מעוררת תגובה שלילית כה חריפה?", "correct_reason": "inflammatory = מסיתה/מלבה. הערות מסיתות מעוררות תגובה שלילית חריפה.", "options_analysis": ["נכון! inflammatory = מסיתה — מתאימה לתגובה שלילית חריפה משני הצדדים", "measured = מדוד — הפוך מהשפעה שמעוררת תגובה חריפה", "diplomatic = דיפלומטית — הפוך מהשפעה שמעוררת תגובה חריפה", "balanced = מאוזנת — הפוך מהשפעה שמעוררת תגובה חריפה"]}', 1.59, 1.0, 0.25, 4, 'ai', NULL, true),
('9a662fea-1ef5-4ae4-b804-688c47a7bf47', 'sentence_completion', 'The scholarship recipient''s ___ background made her academic achievements all the more remarkable.', NULL, '[{"id": "d", "text": "privileged"}, {"id": "a", "text": "disadvantaged"}, {"id": "c", "text": "comfortable"}, {"id": "b", "text": "affluent"}]'::jsonb, 1, '{"strategy": "all the more remarkable = מדהימים אף יותר. איזה רקע הופך הישגים אקדמיים למרשימים במיוחד?", "correct_reason": "disadvantaged = מקופח. הישגים על רקע מקופח נתפסים כמרשימים במיוחד.", "options_analysis": ["privileged = מיוחס — הפוך, לא היה הופך את ההישגים למדהימים במיוחד", "נכון! disadvantaged = מקופח — מתאים להישגים שנתפסים כמרשימים על רקע קשה", "comfortable = נוח — הפוך, לא היה מדגיש את ההישגים כמיוחדים", "affluent = אמיד — הפוך, לא היה מדגיש את ההישגים כמיוחדים"]}', 1.88, 1.0, 0.25, 4, 'ai', NULL, true),
('06fec34f-a806-4c37-980f-8fa3149d650e', 'sentence_completion', 'The committee''s ___ response to the whistleblower''s report only intensified public suspicion of a cover-up.', NULL, '[{"id": "b", "text": "comprehensive"}, {"id": "a", "text": "thorough"}, {"id": "c", "text": "dismissive"}, {"id": "d", "text": "prompt"}]'::jsonb, 2, '{"strategy": "only intensified public suspicion = רק הגביר חשד ציבורי. איזו תגובה לדיווח מגבירה חשד לטיוח?", "correct_reason": "dismissive = מזלזלת/דוחה. תגובה מזלזלת לדיווח מגבירה חשד לטיוח.", "options_analysis": ["comprehensive = מקיפה — הפוך מהשפעה שמגבירה חשד", "thorough = יסודית — הפוך מהשפעה שמגבירה חשד", "נכון! dismissive = מזלזלת — מתאימה לתגובה שמגבירה חשד לטיוח", "prompt = מהירה — לא בהכרח מגבירה חשד כשלעצמה"]}', 1.54, 1.0, 0.25, 4, 'ai', NULL, true),
('21993129-6835-49fb-b4ed-0899be78f588', 'sentence_completion', 'The author''s tendency toward ___ prose often forced readers to reread passages multiple times to grasp their meaning.', NULL, '[{"id": "a", "text": "accessible"}, {"id": "c", "text": "lucid"}, {"id": "d", "text": "clear"}, {"id": "b", "text": "dense"}]'::jsonb, 3, '{"strategy": "forced readers to reread multiple times = הכריח קוראים לקרוא שוב מספר פעמים. איזה סגנון פרוזה דורש קריאה חוזרת?", "correct_reason": "dense = צפוף/כבד. פרוזה צפופה דורשת קריאה חוזרת להבנה.", "options_analysis": ["accessible = נגיש — הפוך מסגנון שדורש קריאה חוזרת", "lucid = בהיר — הפוך מסגנון שדורש קריאה חוזרת", "clear = ברור — הפוך מסגנון שדורש קריאה חוזרת", "נכון! dense = צפוף — מתאים לסגנון שדורש קריאה חוזרת להבנה"]}', 1.38, 1.0, 0.25, 4, 'ai', NULL, true),
('5aec97f1-74a3-4d52-a308-d211d36a009b', 'restatement', 'The candidate''s platform, while appealing to younger voters, largely failed to resonate with the older generation.', NULL, '[{"id": "c", "text": "Although young voters found the platform appealing, it did not connect well with older voters."}, {"id": "a", "text": "The candidate''s platform appealed equally to voters of all ages."}, {"id": "b", "text": "The platform failed to appeal to any voters regardless of age."}, {"id": "d", "text": "Older voters were the platform''s strongest supporters."}]'::jsonb, 0, '{"strategy": "while appealing to younger, failed with older = ניגוד בין קבוצות גיל.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: פנה לצעירים, לא הצליח עם מבוגרים", "הפוך — סותר את ההבדל בין קבוצות הגיל", "הפוך — סותר ''appealing to younger voters''", "הפוך — סותר ''failed to resonate with the older generation''"]}', 1.65, 1.0, 0.25, 4, 'ai', NULL, true),
('c94ab11d-f9cb-42cc-9569-3edbf9c44670', 'restatement', 'The novel''s plot, intricate as it is, never loses sight of its central emotional core.', NULL, '[{"id": "c", "text": "The complexity of the plot causes the novel to lose its emotional focus."}, {"id": "d", "text": "Despite its complexity, the novel remains focused on its main emotional themes."}, {"id": "a", "text": "The novel has no plot to speak of."}, {"id": "b", "text": "The novel''s plot is simple and has no emotional depth."}]'::jsonb, 1, '{"strategy": "intricate as it is, never loses sight = מורכבת ככל שתהיה, לא מאבדת מיקוד. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''never loses sight of its central emotional core''", "נכון! אותה משמעות מדויקת: למרות המורכבות, נשאר ממוקד בנושאים הרגשיים", "סותר את קיום העלילה שתוארה כמורכבת", "הפוך — סותר ''intricate as it is''"]}', 1.59, 1.0, 0.25, 4, 'ai', NULL, true),
('04d9afee-877b-4f7a-964a-9ed992fb67e1', 'restatement', 'The city''s infrastructure investment, substantial as it was, proved insufficient to meet the demands of rapid population growth.', NULL, '[{"id": "d", "text": "The city made no investment in infrastructure at all."}, {"id": "c", "text": "The population never grew, so no investment was needed."}, {"id": "b", "text": "Even though the investment was large, it was not enough to keep pace with the fast-growing population."}, {"id": "a", "text": "The infrastructure investment was more than enough to handle population growth."}]'::jsonb, 2, '{"strategy": "substantial as it was, proved insufficient = משמעותית ככל שהייתה, התבררה כלא מספיקה. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר ''substantial as it was'' — כן הייתה השקעה גדולה", "סותר ''rapid population growth'' — כן הייתה צמיחה", "נכון! אותה משמעות מדויקת: השקעה גדולה אך לא הספיקה לגידול אוכלוסין מהיר", "הפוך — סותר ''proved insufficient''"]}', 1.24, 1.0, 0.25, 4, 'ai', NULL, true),
('cd3b86dc-277d-48cd-bde0-c2f03f4cfa01', 'restatement', 'The diplomat''s measured response, calculated to avoid escalation, was interpreted by critics as a sign of weakness.', NULL, '[{"id": "d", "text": "Critics praised the diplomat''s response as courageous."}, {"id": "c", "text": "The diplomat''s response caused immediate escalation of the conflict."}, {"id": "b", "text": "The diplomat''s response was seen by everyone as a display of strength."}, {"id": "a", "text": "Although designed to prevent escalation, the diplomat''s careful response was viewed by critics as weak."}]'::jsonb, 3, '{"strategy": "calculated to avoid escalation, interpreted as weakness = ניגוד בין כוונה לפרשנות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''a sign of weakness''", "הפוך — סותר ''calculated to avoid escalation''", "הפוך — סותר ''interpreted by critics as a sign of weakness''", "נכון! אותה משמעות מדויקת: נועד למנוע הסלמה, אך מבקרים ראו כחולשה"]}', 1.48, 1.0, 0.25, 4, 'ai', NULL, true),
('b3d6aa2b-af94-4289-bbe9-ee19f5489d97', 'restatement', 'The startup''s founder, celebrated for his vision, was often criticized for his inattention to operational details.', NULL, '[{"id": "a", "text": "While admired for his vision, the founder frequently faced criticism for overlooking operational details."}, {"id": "b", "text": "No one ever had any opinion about the founder''s abilities."}, {"id": "d", "text": "The founder was criticized for lacking vision entirely."}, {"id": "c", "text": "The founder was praised for both his vision and his attention to details."}]'::jsonb, 0, '{"strategy": "celebrated for vision, criticized for inattention = ניגוד בין שני היבטים.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: הוערך על חזון, נבקר על התעלמות מפרטים תפעוליים", "סותר את קיום התגובות המתוארות", "הפוך — סותר ''celebrated for his vision''", "הפוך — סותר ''often criticized for his inattention to operational details''"]}', 1.34, 1.0, 0.25, 4, 'ai', NULL, true),
('11884184-5115-4b0b-bb6a-94866694868e', 'restatement', 'The policy''s short-term costs, though considerable, are expected to be offset by substantial long-term savings.', NULL, '[{"id": "d", "text": "The policy will only generate costs, never savings."}, {"id": "b", "text": "Although the policy is costly in the near term, it should be balanced out by significant savings later."}, {"id": "a", "text": "The short-term costs of the policy are minimal and insignificant."}, {"id": "c", "text": "The policy is expected to have no long-term savings whatsoever."}]'::jsonb, 1, '{"strategy": "though considerable costs, offset by savings = ניגוד זמן קצר-ארוך.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''substantial long-term savings''", "נכון! אותה משמעות מדויקת: יקרה בטווח קצר, אך צפויה להתקזז בחיסכון בטווח ארוך", "הפוך — סותר ''considerable'' costs", "הפוך — סותר ''expected to be offset by substantial long-term savings''"]}', 1.18, 1.0, 0.25, 4, 'ai', NULL, true),
('b23a3e7f-a974-45fe-bb68-894bf0a02836', 'restatement', 'The professor''s grading, notoriously strict, nevertheless earned the respect of students who valued rigorous standards.', NULL, '[{"id": "c", "text": "No students ever had an opinion about the professor''s grading."}, {"id": "a", "text": "Students despised the professor for having overly strict grading standards."}, {"id": "b", "text": "Even though known for being very strict, the professor''s grading earned respect from students who appreciated high standards."}, {"id": "d", "text": "The professor was known for being extremely lenient in grading."}]'::jsonb, 2, '{"strategy": "notoriously strict, nevertheless earned respect = ניגוד בין תכונה קשה לתוצאה חיובית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום התגובות המתוארות", "הפוך — סותר ''earned the respect of students''", "נכון! אותה משמעות מדויקת: ידוע כמחמיר, אך זכה בכבוד תלמידים שהעריכו סטנדרטים", "הפוך — ''lenient'' סותר ''notoriously strict''"]}', 1.4, 1.0, 0.25, 4, 'ai', NULL, true),
('c58529da-6cae-4090-bc3f-e398779a4997', 'restatement', 'The merger, contentious among shareholders, ultimately proceeded after months of heated debate.', NULL, '[{"id": "b", "text": "The merger was cancelled due to shareholder opposition."}, {"id": "d", "text": "Shareholders unanimously supported the merger from the start."}, {"id": "c", "text": "No debate ever took place regarding the merger."}, {"id": "a", "text": "Despite being controversial among shareholders, the merger went forward after extensive debate."}]'::jsonb, 3, '{"strategy": "contentious, ultimately proceeded = שנוי במחלוקת, בסופו של דבר יצא לפועל. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''ultimately proceeded''", "הפוך — סותר ''contentious among shareholders''", "סותר ''months of heated debate''", "נכון! אותה משמעות מדויקת: שנוי במחלוקת, אך יצא לפועל אחרי דיון ממושך"]}', 1.83, 1.0, 0.25, 4, 'ai', NULL, true),
('2ac25a2a-fbd4-4589-80c8-85df4dfa7d2e', 'restatement', 'The region''s economy, heavily dependent on tourism, was devastated when travel restrictions were imposed.', NULL, '[{"id": "d", "text": "Because the economy relied so heavily on tourism, it suffered severely when travel was restricted."}, {"id": "b", "text": "Travel restrictions actually strengthened the region''s economy."}, {"id": "c", "text": "The region''s economy was unaffected by any travel restrictions."}, {"id": "a", "text": "The region''s economy had no connection to tourism at all."}]'::jsonb, 0, '{"strategy": "heavily dependent...devastated when restricted = סיבה-תוצאה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: תלות כבדה בתיירות הובילה לפגיעה חמורה בעקבות הגבלות", "הפוך — סותר ''was devastated''", "הפוך — סותר ''was devastated when travel restrictions were imposed''", "סותר ''heavily dependent on tourism''"]}', 1.78, 1.0, 0.25, 4, 'ai', NULL, true),
('cb9a34ba-6814-4823-a283-86e3df208482', 'restatement', 'The report''s findings, alarming as they were, prompted swift action from regulators.', NULL, '[{"id": "a", "text": "The findings were so unremarkable that regulators ignored them entirely."}, {"id": "d", "text": "Because the findings were so troubling, regulators acted quickly in response."}, {"id": "c", "text": "The report contained no findings of any significance."}, {"id": "b", "text": "Regulators took no action despite the alarming findings."}]'::jsonb, 1, '{"strategy": "alarming, prompted swift action = מטרידים, הביאו לפעולה מהירה. סיבה-תוצאה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''alarming as they were''", "נכון! אותה משמעות מדויקת: ממצאים מטרידים הביאו לפעולה מהירה של הרגולטורים", "סותר את קיום הממצאים שתוארו", "הפוך — סותר ''prompted swift action from regulators''"]}', 1.85, 1.0, 0.25, 4, 'ai', NULL, true),
('e247e5c1-6801-4d8d-8403-4950f075109d', 'restatement', 'The team''s morale, badly shaken by the recent losses, began to recover after the coach''s motivational speech.', NULL, '[{"id": "b", "text": "The coach''s speech made the team''s morale worse."}, {"id": "c", "text": "The team''s morale was never affected by the losses."}, {"id": "d", "text": "After the losses damaged team morale, the coach''s speech helped it start to improve."}, {"id": "a", "text": "The team never experienced any losses."}]'::jsonb, 2, '{"strategy": "badly shaken, began to recover = ניגוד עבר-הווה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''began to recover''", "הפוך — סותר ''badly shaken by the recent losses''", "נכון! אותה משמעות מדויקת: אחרי שהפסדים פגעו במורל, הנאום עזר לו להתחיל להשתפר", "סותר ''the recent losses''"]}', 1.87, 1.0, 0.25, 4, 'ai', NULL, true),
('2701361e-5b83-4467-8fdc-6c16c863afe2', 'restatement', 'The city''s aging power grid, despite periodic upgrades, remains vulnerable to failures during extreme weather.', NULL, '[{"id": "c", "text": "Extreme weather has no effect on the power grid whatsoever."}, {"id": "b", "text": "The power grid is now completely immune to weather-related failures."}, {"id": "d", "text": "The power grid has never received any upgrades."}, {"id": "a", "text": "Even with occasional upgrades, the power grid is still susceptible to breakdowns in severe weather."}]'::jsonb, 3, '{"strategy": "despite upgrades, remains vulnerable = ניגוד בין שיפור לבעיה נמשכת.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''remains vulnerable to failures during extreme weather''", "הפוך — סותר ''remains vulnerable to failures''", "הפוך — סותר ''despite periodic upgrades''", "נכון! אותה משמעות מדויקת: למרות שדרוגים מזדמנים, עדיין רגישה לתקלות במזג אוויר קיצוני"]}', 1.6, 1.0, 0.25, 4, 'ai', NULL, true),
('c1caba31-e90f-4cd6-8641-4be0890c7caa', 'reading_comprehension', 'What is the main purpose of the passage?', 'bdaa277c-f414-4112-97cd-6a9acf95ae32', '[{"id": "d", "text": "To explain the Dunning-Kruger effect and discuss a statistical critique of it"}, {"id": "b", "text": "To promote a specific method for improving self-assessment skills"}, {"id": "a", "text": "To argue that all experts are more competent than novices"}, {"id": "c", "text": "To provide a complete biography of David Dunning and Justin Kruger"}]'::jsonb, 0, '{"strategy": "שאלת מטרה/רעיון מרכזי — הפסקה מסבירה את אפקט דנינג-קרוגר ודנה בביקורת סטטיסטית עליו.", "correct_reason": "הפסקה מגדירה את המושג, מסבירה מנגנון, ומציגה ביקורת מחקרית.", "options_analysis": ["נכון! הסבר האפקט ודיון בביקורת סטטיסטית עליו = המטרה המרכזית", "לא מוזכר בפסקה כלל", "לא נאמר בפסקה כלל — זה לא הנושא הנדון", "לא מוזכר בפסקה כלל — הפסקה עוסקת ברעיון, לא בביוגרפיה"]}', 1.39, 1.0, 0.25, 4, 'ai', NULL, true),
('de5bdc89-e6b7-4f59-9c97-f0eccc4132b3', 'reading_comprehension', 'According to the passage, why do people with limited skill in a domain tend to overestimate their competence?', 'bdaa277c-f414-4112-97cd-6a9acf95ae32', '[{"id": "c", "text": "Because experts intentionally mislead them"}, {"id": "a", "text": "Because the same skills needed to perform well are needed to accurately evaluate one''s own performance, and they lack both"}, {"id": "b", "text": "Because they have received extensive training"}, {"id": "d", "text": "Because they deliberately lie about their abilities"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את ההסבר לתופעה בפסקה.", "correct_reason": "הפסקה אומרת: ''the very skills required to perform a task well are often the same skills needed to accurately evaluate one''s own performance; a person who lacks competence...therefore also lacks the metacognitive ability to recognize that lack''.", "options_analysis": ["לא נאמר בפסקה כלל", "נכון! נאמר במפורש בפסקה", "הפוך — הפסקה עוסקת דווקא במי שחסר מיומנות", "לא נאמר בפסקה — אין רמז לכוונה מודעת להטעיה"]}', 1.37, 1.0, 0.25, 4, 'ai', NULL, true),
('474f7d5e-1ed0-4167-be43-4236854a668a', 'reading_comprehension', 'The word "acutely" in the passage most closely means:', 'bdaa277c-f414-4112-97cd-6a9acf95ae32', '[{"id": "c", "text": "barely"}, {"id": "a", "text": "occasionally"}, {"id": "d", "text": "intensely or sharply"}, {"id": "b", "text": "incorrectly"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''experts...tend to be acutely aware of the complexity of their field''.", "correct_reason": "acutely = בחדות/באופן אינטנסיבי.", "options_analysis": ["הפוך גמור למשמעות המילה", "לא מדויק למשמעות המילה", "נכון! acutely = בחדות/באופן אינטנסיבי", "לא קשור למשמעות המילה"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('f77a98e7-fabb-4435-8d8a-114622d2b2ae', 'reading_comprehension', 'According to the passage, why do experts sometimes underestimate their relative ability?', 'bdaa277c-f414-4112-97cd-6a9acf95ae32', '[{"id": "b", "text": "They have no real expertise in their field"}, {"id": "d", "text": "They are unaware that their field is complex"}, {"id": "c", "text": "They deliberately downplay their skills to appear humble"}, {"id": "a", "text": "They mistakenly assume tasks that come easily to them are equally easy for everyone else"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את ההסבר לתופעה אצל מומחים בפסקה.", "correct_reason": "הפסקה אומרת: ''may mistakenly assume that tasks which come easily to them are equally easy for everyone else, leading them to underrate their own distinctiveness''.", "options_analysis": ["סותר את התיאור בפסקה שהם דווקא בעלי מומחיות רבה", "הפוך — הפסקה אומרת שהם מודעים היטב למורכבות תחומם", "לא נאמר בפסקה — אין רמז לכוונה מודעת", "נכון! נאמר במפורש בפסקה"]}', 1.31, 1.0, 0.25, 4, 'ai', NULL, true),
('ced40798-0e7d-4092-b6ec-ad22e4f438e3', 'reading_comprehension', 'What critique of the Dunning-Kruger effect is mentioned in the passage?', 'bdaa277c-f414-4112-97cd-6a9acf95ae32', '[{"id": "b", "text": "That part of the observed pattern may be attributable to a statistical phenomenon called regression to the mean, rather than genuine psychological deficiency"}, {"id": "a", "text": "That it has never been studied by any psychologist"}, {"id": "d", "text": "That the effect only applies to children, never adults"}, {"id": "c", "text": "That Dunning and Kruger fabricated their entire study"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הביקורת הסטטיסטית בפסקה.", "correct_reason": "הפסקה אומרת: ''some statisticians have argued that at least part of the observed pattern can be attributed to a purely statistical phenomenon known as regression to the mean, rather than to any genuine psychological deficiency''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "סותר את כל התיאור בפסקה של המחקר המקורי", "לא נאמר בפסקה כלל", "לא נאמר בפסקה — אין טענה כזו על זיוף"]}', 1.77, 1.0, 0.25, 4, 'ai', NULL, true);